pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint128 deposit1, uint128 deposit2, uint128 collectWad, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(deposit1 > 0 && deposit2 > 0);
        vm.assume(collectWad > 0 && collectWad <= deposit1);

        // 1. initial deposit
        vm.deal(actor, uint256(deposit1) + uint256(deposit2));
        vm.prank(actor);
        c.Deposit{value: uint256(deposit1)}();

        // 2. set min sum and initialize
        c.SetMinSum(0);
        c.Initialized();

        // 3. collect part of the first deposit
        vm.prank(actor);
        c.Collect(uint256(collectWad));

        // 4. second deposit
        vm.prank(actor);
        c.Deposit{value: uint256(deposit2)}();

        // 5. property: balance of actor must equal first deposit - collect amount + second deposit
        uint256 expected = uint256(deposit1) - uint256(collectWad) + uint256(deposit2);
        assertTrue(c.balances(actor) == expected);
    }
}

