pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint128 deposit1, uint128 collectAmt, uint128 deposit2, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(deposit1 > 0);
        vm.assume(deposit2 > 0);
        vm.assume(collectAmt > 0);
        vm.assume(deposit1 >= collectAmt);
        vm.assume(uint256(deposit1) + uint256(collectAmt) + uint256(deposit2) <= type(uint128).max);

        c.Initialized();

        vm.deal(actor, uint256(deposit1) + uint256(deposit2));

        vm.prank(actor);
        c.Deposit{value: deposit1}();

        vm.prank(actor);
        c.Collect(collectAmt);

        uint256 balAfterCollect = c.balances(actor);
        uint256 expectedAfterCollect = deposit1 - collectAmt;
        assertTrue(balAfterCollect == expectedAfterCollect);

        vm.prank(actor);
        c.Deposit{value: deposit2}();

        uint256 finalBal = c.balances(actor);
        uint256 expectedFinal = expectedAfterCollect + deposit2;
        assertTrue(finalBal == expectedFinal);
    }
}

